export interface PairRef {
  a: ChannelRef;
  b: ChannelRef;
}

/**
 * A reflector of ``diameter_m`` metres with aperture ``efficiency`` (a PETAL dish).
 *
 * Below 3 wavelengths across it is electrically small (``core.antennas``).
 */
export interface ParabolicAntenna {
  diameter_m: number;
  efficiency?: number;
  type: "parabolic";
}

export interface Preset {
  description: string;
  name: string;
}

/**
 * All processing settings; every section has defaults.
 */
export interface ProcessingConfig {
  caf?: CafConfig;
  calibration?: CalibrationConfig;
  capture?: CaptureConfig;
  detection?: DetectionConfig;
  region?: Region;
  solver?: SolverConfig;
  uncertainty?: UncertaintyConfig;
}

/**
 * Work the server has in hand.
 */
export interface QueueStatus {
  captures_pending: number;
  jobs_running: number;
  jobs_waiting: number;
}

/**
 * One receive chain of a site: antenna, pointing, noise and its spectrum monitors.
 *
 * system_noise_temp_k: system noise temperature, K. polarization_loss_db: loss applied
 * to everything this channel receives, dB. max_sample_rate_hz: highest complex sample
 * rate, Hz. monitors: explicit spectrum windows; when empty, ``SystemConfig`` derives
 * one per transponder of each watched satellite.
 */
export interface ReceiveChannel {
  antenna: IsotropicAntenna | ParabolicAntenna | BeamAntenna | TableAntenna;
  id: string;
  max_sample_rate_hz?: number;
  monitors?: Monitor[];
  name?: string;
  pointing: TrackPointing | FixedPointing;
  polarization_loss_db?: number;
  system_noise_temp_k?: number;
}

/**
 * Latitude/longitude box of admissible emitter positions, degrees.
 *
 * ``lon_min = -180`` with ``lon_max = 180`` is the full circle. Otherwise the box
 * runs eastward from ``lon_min`` to ``lon_max``; ``lon_max < lon_min`` wraps the
 * antimeridian, and equal values (or -180 against 180 the other way round) are
 * invalid.
 */
export interface Region {
  lat_max?: number;
  lat_min?: number;
  lon_max?: number;
  lon_min?: number;
}

/**
 * A satellite: its orbit and its transponders.
 *
 * ephemeris_sigma: RIC one-sigma override; otherwise the sigmas follow the orbit type
 * (``tle`` -> ``uncertainty.ephemeris.tle``, everything else -> ``operator``).
 */
export interface Satellite {
  ephemeris_sigma?: EphemerisSigma | null;
  id: string;
  name: string;
  norad_id?: number | null;
  notes?: string;
  orbit: TleOrbitModel | GeoOrbitModel | KeplerOrbitModel | TableOrbitModel;
  transponders: Transponder[];
}

/**
 * A simulated world: emitters plus truth errors.
 */
export interface Scenario {
  description?: string;
  emitters?: EmitterSpec[];
  errors?: TruthErrors;
  name: string;
  seed?: number;
}

/**
 * ``GET /sim/scenario`` and the reply to ``PUT /sim/scenario`` (whose request body
 * is a bare ``Scenario``).
 */
export interface ScenarioEnvelope {
  scenario: Scenario;
  version: number;
}

/**
 * ``GET /sim/truth``: simulated truth (fictional; label it SIMULATION wherever it
 * is shown). ``events`` covers the active events.
 */
export interface SimTruth {
  emitters: SimTruthEmitter[];
  events: SimTruthEvent[];
  simulated?: boolean;
  version: number;
}

/**
 * A simulated emitter with every default resolved. ``active`` is enabled and
 * inside its on/off times now.
 */
export interface SimTruthEmitter {
  active: boolean;
  bandwidth_hz: number;
  eirp_dbw: number;
  enabled: boolean;
  freq_hz: number;
  id: string;
  kind: "jammer" | "carrier" | "local";
  lat_deg: number;
  lon_deg: number;
  name: string;
  waveform: string;
}

export interface SimTruthEvent {
  emitter_id: string | null;
  event_id: string;
  inside_ellipse: boolean | null;
  miss_m: number | null;
}

/**
 * A ground site. The antenna phase centre is at ``alt_m + antenna_height_m`` above
 * the WGS84 ellipsoid (``xyz()``); ``antenna_height_m`` (above ground) also sets the
 * radio horizon of direct paths.
 */
export interface Site {
  alt_m?: number;
  antenna_height_m?: number;
  channels: ReceiveChannel[];
  clock?: SiteClock;
  id: string;
  lat_deg: number;
  lon_deg: number;
  name: string;
}

/**
 * Site time reference. sigma_ns: one-sigma clock offset, ns.
 */
export interface SiteClock {
  sigma_ns?: number;
}

/**
 * How the ellipse shrank as measurements accumulated.
 */
export interface SolutionHistoryRow {
  n_measurements: number;
  semi_major_m: number;
  semi_minor_m: number;
  t_ns: NsString;
}

/**
 * A position estimate (``core.solver.Solution.as_dict()``).
 *
 * Covariances are 2x2, m^2, ordered [east, north]. ``residuals`` are whitened and
 * in the order of the measurements used. ``ambiguities`` are the other admissible
 * solutions (for example the mirror image across the equator); they carry no
 * ambiguities of their own. ``dominant_error`` is one of ``noise``,
 * ``ephemeris_position``, ``ephemeris_velocity``, ``clock``, ``oscillator``,
 * ``tdoa_bias``, ``reference`` (``core.solver.ERROR_SOURCES``).
 */
export interface SolutionOut {
  ambiguities: SolutionOut[];
  ambiguity_resolved_by: "none" | "region" | "measurements" | "unresolved";
  cep50_m: number;
  chi2: number;
  converged: boolean;
  cov_consider_en_m2: number[][];
  cov_en_m2: number[][];
  cov_noise_en_m2: number[][];
  dof: number;
  dominant_error: string;
  ellipse: EllipseOut;
  height_m: number;
  lat_deg: number;
  lon_deg: number;
  n_measurements: number;
  reduced_chi2: number | null;
  residuals: number[];
}

/**
 * Enough of a solution to draw it on the map and list it.
 */
export interface SolutionSummary {
  ambiguous: boolean;
  azimuth_deg: number;
  cep50_m: number;
  lat_deg: number;
  lon_deg: number;
  semi_major_m: number;
  semi_minor_m: number;
}

/**
 * Position solver settings (MATH.md section 9).
 */
export interface SolverConfig {
  chi2_ambiguity?: number;
  confidence?: number;
  grid_step_deg?: number;
  height_m?: number;
  max_measurements?: number;
  min_elevation_deg?: number;
  n_starts?: number;
}

/**
 * ``GET /status``.
 */
export interface Status {
  config_version: number;
  events_active: number;
  nodes: NodeStatus[];
  queue: QueueStatus;
  server_t_ns: NsString;
}

export interface Subpoint {
  alt_m: number;
  lat_deg: number;
  lon_deg: number;
  sat_id: string;
}

/**
 * A complete system: satellites, sites, the frequency plan and processing settings.
 *
 * version: revision of this configuration (the server's ETag). dut1_s: UT1 - UTC, s.
 */
export interface SystemConfig {
  carriers?: Carrier[];
  description?: string;
  dut1_s?: number;
  name: string;
  processing?: ProcessingConfig;
  satellites: Satellite[];
  sites: Site[];
  version?: number;
}

/**
 * A tabulated axisymmetric pattern: gain (dBi) against off-axis angle (degrees,
 * strictly increasing within [0, 180]); linear interpolation in dB, ends held.
 */
export interface TableAntenna {
  gain_dbi: number[];
  theta_deg: number[];
  type: "table";
}

/**
 * Operator ephemeris table in ECEF, cubic Hermite interpolated; never extrapolated.
 */
export interface TableOrbitModel {
  samples: TableSample[];
  type: "table";
}

/**
 * One ephemeris sample: time, ECEF position (m) and ECEF velocity dr/dt (m/s).
 */
export interface TableSample {
  r_m: number[];
  t: string;
  v_mps: number[];
}

/**
 * What capture tasking is doing for an event (null until tasking has looked at it).
 *
 * state: ``waiting`` (the next round is scheduled), ``capturing`` (IQ captures
 * requested from the nodes), ``processing`` (correlating, calibrating, solving) or
 * ``idle`` (nothing to capture: no usable channel sees the event, or no second
 * satellite with a usable channel relays it, so it cannot be located).
 * rounds: capture rounds started for the event. last_round_ns / next_round_ns: server
 * time of the last round's start and of the next one (null when none is planned).
 * channels: the receive channels of the last round, primary first.
 * message: one plain sentence about the last round (what failed and is being
 * retried, what is awaited), or null when all went well.
 * solve_reason: why the last solve gave no position (for example ``unobservable``
 * or ``fewer than two accepted measurements``); null after a successful solve.
 */
export interface TaskingStatus {
  channels: string[];
  last_round_ns: NsString | null;
  message: string | null;
  next_round_ns: NsString | null;
  rounds: number;
  solve_reason: string | null;
  state: "waiting" | "capturing" | "processing" | "idle";
}

/**
 * Two-line element set propagated with SGP4 (uses the ``tle`` ephemeris sigmas).
 *
 * line1, line2: the two lines, 69 characters each with valid checksums.
 */
export interface TleOrbitModel {
  line1: string;
  line2: string;
  type: "tle";
}

/**
 * Boresight follows a satellite (recomputed from its orbit).
 */
export interface TrackPointing {
  satellite_id: string;
}

/**
 * A change of an event's state or verdict (or a merge or split noted against it).
 * ``reason`` says why in plain words, for example ``all detections released``,
 * ``detected again``, ``closed by operator`` or ``merged into EV-000012``.
 */
export interface Transition {
  reason?: string | null;
  state: "detected" | "characterizing" | "locating" | "located" | "lost" | "closed";
  t_ns: NsString;
  verdict: "uplink" | "local" | "undetermined";
}

/**
 * One bent-pipe transponder.
 *
 * uplink_center_hz, bandwidth_hz: uplink passband, Hz. translation_hz: signed,
 * downlink = uplink + translation. g_over_t_dbk: receive G/T, dB/K. sfd_dbw_m2:
 * saturating flux density, dBW/m^2. eirp_sat_dbw: saturated EIRP, dBW.
 * group_delay_s: transponder group delay, s.
 */
export interface Transponder {
  bandwidth_hz: number;
  eirp_sat_dbw: number;
  g_over_t_dbk: number;
  group_delay_s?: number;
  id: string;
  sfd_dbw_m2: number;
  translation_hz: number;
  uplink_center_hz: number;
}

/**
 * How the simulated world differs from what the system believes.
 *
 * ephemeris: per satellite id. sat_osc_frac: fractional error of each satellite's
 * translation oscillator. site_clock_offset_ns: ``delta_g`` per site, true time
 * minus labelled time, ns. site_osc_frac: fractional error of each site's reference
 * oscillator (``eps_g``). iono: ionospheric delay.
 */
export interface TruthErrors {
  ephemeris?: Record<string, EphemerisError>;
  iono?: IonoError;
  sat_osc_frac?: Record<string, number>;
  site_clock_offset_ns?: Record<string, number>;
  site_osc_frac?: Record<string, number>;
}

/**
 * Systematic (consider) uncertainties, all one-sigma.
 *
 * sat_osc_frac: fractional error of a satellite's translation oscillator,
 * uncalibrated. site_osc_frac: fractional error of a site's reference oscillator.
 * tdoa_bias_ns: per-pair TDOA bias, ns.
 */
export interface UncertaintyConfig {
  ephemeris?: EphemerisUncertainty;
  sat_osc_frac?: number;
  site_osc_frac?: number;
  tdoa_bias_ns?: number;
}

/**
 * ``POST /config/validate`` (always HTTP 200; ``ok`` says whether it validates).
 */
export interface ValidateResult {
  errors: FieldProblem[];
  ok: boolean;
  warnings: FieldProblem[];
}

/**
 * What an emitter transmits (MATH.md section 4, deterministic waveforms).
 *
 * type: ``cw`` (carrier), ``noise`` (band-limited Gaussian noise), ``chirp``
 * (linear sweep across ``bandwidth_hz`` every ``sweep_period_s``) or ``psk``
 * (root-raised-cosine PSK of ``order`` at ``symbol_rate_hz`` with ``rolloff``).
 * bandwidth_hz: occupied bandwidth, Hz (noise and chirp; ignored for cw; for psk it
 * is derived as ``symbol_rate_hz * (1 + rolloff)`` when left at 0).
 * duty, period_s: on/off gating; ``duty = 1`` or ``period_s = 0`` is continuous.
 * seed: distinguishes otherwise identical emitters.
 */
export interface WaveformSpec {
  bandwidth_hz?: number;
  duty?: number;
  order?: 2 | 4 | 8;
  period_s?: number;
  rolloff?: number;
  seed?: number;
  sweep_period_s?: number;
  symbol_rate_hz?: number;
  type?: "cw" | "noise" | "chirp" | "psk";
}

export interface WsConfigMessage {
  config_version: number;
  type?: "config";
}

export interface WsEventMessage {
  event: Event;
  type?: "event";
}

export interface WsSimMessage {
  type?: "sim";
  version: number;
}

/**
 * About once a second.
 */
export interface WsStatusMessage {
  config_version: number;
  events_active: number;
  marking: Marking | null;
  nodes: NodeStatus[];
  queue: QueueStatus;
  server_t_ns: NsString;
  simulation: boolean;
  type?: "status";
}

/**
 * Browser to server: which spectrum windows to stream, as
 * ``[channel_id, monitor_id]`` pairs (replaces the previous selection).
 */
export interface WsSubscribe {
  psd?: [string, string][];
  type?: "subscribe";
}

